        button submit=true
    list row.Term order=until empty="No terms recorded"@{nl="Geen termijnen vastgelegd"}
     card "Recorded term"@{nl="Vastgelegde termijn"}
      ## Lifecycle strip: each stage shows its live flag beside the frozen record.
      steps
       slot item
        status row.executed
       slot item
        status row.expired
       slot item
        status row.terminated
      text row.file,row.from,row.until,row.pricing,row.currency,row.notice_days,row.notice_date,row.timezone,row.snapshot
      text row.reason
