        calendar until
        input notice_days
        textarea pricing
        input currency
       button submit=true
      button opens=execute_term
      modal "Execute agreement"@{nl="Overeenkomst ondertekenen"} id=execute_term
       slot content
        alert "Execution freezes the file, dates and party snapshot."@{nl="Ondertekening legt het bestand, de data en de partijsnapshot vast."}
        form execute arguments={term=row}
      tooltip "Record a renewal linked to this term"@{nl="Leg een verlenging vast die naar deze termijn verwijst"}
       button opens=renew_term
