      tab "Reminder outcomes"@{nl="Herinneringsresultaten"}
       alert "Failed or unavailable deliveries need legal review; skipped reminders are obsolete, not failed."@{nl="Mislukte of onbeschikbare bezorgingen vereisen juridische beoordeling; overgeslagen herinneringen zijn achterhaald, niet mislukt."}
       table row.NoticeDelivery columns=obligation,revision order=-created empty="No reminders recorded"@{nl="Geen herinneringen vastgelegd"}
        badge row.state
