       list row.Amendment empty="No amendments recorded"@{nl="Geen aanvullingen vastgelegd"}
        text row.text,row.file,row.author
        pagination
     details "Term history"@{nl="Termijnhistorie"}
      text row.previous
      diff
       slot before
        text row.previous?.file,row.previous?.from,row.previous?.until,row.previous?.pricing,row.previous?.currency
       slot after
