    parcel_item.notification,parcel_item.state,event.delivery_id,event.status,event.result,event.error,attempt.status,attempt.result,attempt.error -> parcel_item.state,parcel_item.notice_state
    attempt,received,attempt.id,succeeded,{reference="accepted-mail"},null,succeeded,{reference="accepted-mail"},null -> notified,succeeded
