  ## Committed identities locate current revisions; each hold has independent durable work.
  scenario revision_created on=Revision.created
   do
    for changed in Revision as row where row.id==event.id limit=1
     emit HoldProgress {revision=changed}
  scenario revision_updated on=Revision.updated
   do
    for changed in Revision as row where row.id==event.id limit=1
     emit HoldProgress {revision=changed}
  ## Old records need no new global scan: admit one authorized addressed recovery.
  scenario recover_hold(revision:Revision) by=salesperson label="Resume hold follow-up"@{nl="Voorraadopvolging hervatten"}
   require can_work(actor,revision.parent.location)
   do emit HoldProgress {revision}
   examples seed=[test_worker] revision=current_offer
    as,request.revision.version -> revision.state
    salesperson,1 -> sent
    salesperson,0 -> error(conflict)
    members,1 -> error(forbidden)
  scenario expire_holds on=HoldProgress
   do
    let revision=event.revision
    let key=format("offer-hold:{id}",{id=revision.id})
    if revision.hold_state in [pending,held,unknown] and revision.held_until!=null
     if revision.state in [withdrawn,declined]
      cancel key
      set revision {hold_state=releasing}
     else
      if revision.held_until<=now
       cancel key
       set revision {hold_state=expired}
      else
       schedule key at=revision.held_until event=HoldDeadline {revision,until=revision.held_until}
    else
     cancel key
    if revision.hold_state==releasing and revision.state!=accepted and revision.hold_release==null
     require revision.resource!=null
     send Rooms.release_offer {source=revision.id,revision=revision.number,resource=revision.resource,reason="Quote hold expired or withdrawn"} as release
     set revision {hold_release=release.id}
   examples seed=[priced_item] event={revision=current_offer}
    current_offer.resource,current_offer.state,current_offer.hold_state,current_offer.held_until,current_offer.hold_release -> current_offer.hold_state,current_offer.hold_release==null
    "office",sent,held,now-1m,null -> expired,true
    "office",sent,pending,now+1h,null -> pending,true
    "office",declined,unknown,now+1h,null -> releasing,false
    "office",withdrawn,releasing,now+1h,"release" -> releasing,false
    "office",accepted,held,now-1m,null -> expired,true
    "office",accepted,released,now-1m,null -> released,true
  scenario hold_deadline on=HoldDeadline
   do
    if event.revision.held_until==event.until and event.until<=now and event.revision.hold_state in [pending,held,unknown]
     if event.revision.state in [withdrawn,declined]
      set event.revision {hold_state=releasing}
     else
      set event.revision {hold_state=expired}
   examples seed=[priced_item] event={revision=current_offer,until=now-1m}
    current_offer.state,current_offer.hold_state,current_offer.held_until -> current_offer.hold_state,current_offer.state
    sent,held,now-1m -> expired,sent
    accepted,held,now-1m -> expired,accepted
    declined,unknown,now-1m -> releasing,declined
    sent,held,now+1h -> held,sent
    sent,released,now-1m -> released,sent
  scenario hold_released on=Rooms.release_offer.completed
   do
    for revision in Revision as row where row.hold_release==event.delivery_id limit=1
     if event.status==succeeded and event.result!=null and event.result.source==revision.id and event.result.revision==revision.number and event.result.kind==release and event.result.state==released
      set revision {hold_state=released}
  scenario retry_hold_release(revision:Revision) by=salesperson label="Retry hold release"@{nl="Vrijgave voorraad opnieuw proberen"}
   require can_work(actor,revision.parent.location) and revision.hold_state==releasing
   do set revision {hold_release=null}
