    manager,fresh,false,[{source="job-1",revision=1,location=test_site.id,from=unavailable_run.from,until=unavailable_run.until,metric=backlog,quantity=1,unit="job"}] -> null,null,partial,false
    manager,fresh,true,[{source="job-1",revision=1,location=test_site.id,from=unavailable_run.from,until=unavailable_run.until,metric=backlog,quantity=1,unit="job"}] -> 1,null,fresh,true
 Then
  # Compare booked and recorded occupancy, cash receipts, balances and service backlog. @{nl="Vergelijk gereserveerde en vastgelegde bezetting, ontvangen betalingen, saldi en serviceachterstand."}
