  crud Account by=account_manager fields=manager,email,renewal,risk,risk_reason,notes,agreement,membership,active create_fields=location,manager,email,renewal,risk,risk_reason,notes,agreement,membership when=can_work(actor,row.location) and account_manager(row.manager) and can_work(row.manager,row.location) delete=none
